hp=base/'coupled-3d/crow-3d-hessian.json';ap=base/'articulated-hand-response/crow-articulated-hand-response.json';h=json.loads(hp.read_text());b=json.loads(ap.read_text());nv=b['nv'];M=np.array(b['M']).reshape(nv,nv);Jb=np.array(b['J']).reshape(3,nv);Xb=np.array(b['X']).reshape(3,nv).T;K0=np.array(h['hessian']);m=np.array(h['masses']);dt=.000125;z=np.arange(9)/8;shape=np.minimum(z,1-z);xbase=np.array([[.2e-6*np.sin(np.pi*t),25e-6*(3*u-4*u**3),8e-6*np.sin(np.pi*t)] for t,u in zip(z,shape)]).flatten();vr=np.array([[.01*np.cos(np.pi*t),.02*np.cos(2*np.pi*t),.01*np.sin(np.pi*t)] for t in z]).flatten();vb=np.zeros(nv);vb[:6]=[.01,-.005,.004,.2,-.1,.15];names={v['name']:v['v'] for v in b['dofs']};vb[names['crow_left_elbow_flex']]=.1;vb[names['crow_left_wrist_flex']]=-.1
